<?php
declare(strict_types=1);require __DIR__.'/app/bootstrap.php';$u=current_user($pdo);$id=(string)($_GET['id']??'');$source=source_access($pdo,$id,$u);if(!$source){http_response_code(404);exit('Source not found.');}
$q=$pdo->prepare("SELECT a.public_id,a.text_commentary,a.audio_commentary_path,a.published_at,u.username,u.display_name,c.selected_text,c.start_seconds,c.end_seconds,c.screenshot_target_path,at.status transcript_status,COALESCE(at.edited_text,at.raw_text) transcript_text FROM annotations a JOIN users u ON u.id=a.user_id JOIN captures c ON c.id=a.capture_id LEFT JOIN annotation_transcripts at ON at.annotation_id=a.id WHERE a.source_id=? AND a.status='published' ORDER BY a.published_at DESC");$q->execute([$source['id']]);$annotations=array_values(array_filter($q->fetchAll(),fn($row)=>annotation_access($pdo,(string)$row['public_id'],$u)!==null));
$q=$pdo->prepare('SELECT id,version_number,captured_at,title,content_hash,screenshot_path FROM source_versions WHERE source_id=? ORDER BY version_number DESC');$q->execute([$source['id']]);$versions=$q->fetchAll();
$events=[];try{$q=$pdo->prepare('SELECT sce.*,pv.version_number previous_number,nv.version_number new_number FROM source_change_events sce LEFT JOIN source_versions pv ON pv.id=sce.previous_version_id JOIN source_versions nv ON nv.id=sce.new_version_id WHERE sce.source_id=? ORDER BY sce.created_at DESC');$q->execute([$source['id']]);$events=$q->fetchAll();}catch(PDOException $e){}
$watched=false;if($u){try{$q=$pdo->prepare('SELECT 1 FROM source_watches WHERE source_id=? AND user_id=?');$q->execute([$source['id'],$u['id']]);$watched=(bool)$q->fetchColumn();}catch(PDOException $e){}}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=h($source['title']?:$source['domain'])?> · Annotated</title><link rel="stylesheet" href="/assets/css/app.css"></head><body><header class="topbar"><a class="brand" href="/">Annotated</a><nav><?php if($u):?><a href="/home.php">Home</a><?php endif?><a href="/explore.php">Explore</a><a href="/search.php">Search</a><?php if($u):?><a href="/saved.php">Saved</a><a href="/notifications.php">Notifications</a><?php endif?></nav></header><main class="layout"><section><div class="sourceHero"><div class="meta"><?=h($source['domain'])?> · <?=h(ucfirst($source['source_type']))?></div><h1><?=h($source['title']?:$source['canonical_url'])?></h1><div class="inlineActions"><a class="button secondary" href="<?=h($source['canonical_url'])?>" target="_blank" rel="noopener">Original source ↗</a><?php if($u):?><button class="button secondary" id="watch"><?=$watched?'Watching':'Watch source'?></button><?php endif?></div><?php if($source['status']==='edited'):?><div class="integrityAlert"><strong>Source edited after annotation</strong><p>At least one previously annotated passage no longer matches the latest captured version.</p></div><?php elseif($source['status']==='updated'):?><div class="integrityAlert mild"><strong>Source updated</strong><p>The page changed, but existing annotated passages were still found.</p></div><?php endif?></div><h2>Annotations · <?=count($annotations)?></h2><?php if(!$annotations):?><div class="card empty">No accessible annotations yet.</div><?php endif?><?php foreach($annotations as $a):?><article class="card"><div class="meta"><strong><?=h($a['display_name'])?></strong> @<?=h($a['username'])?> · <?=h($a['published_at'])?></div><?php if($a['text_commentary']):?><p><?=nl2br(h($a['text_commentary']))?></p><?php endif?><?php if($a['selected_text']):?><blockquote><?=h($a['selected_text'])?></blockquote><?php endif?><?php if($a['audio_commentary_path']):?><audio class="wideAudio" controls src="<?=h(evidence_url($a['public_id'],'audio'))?>"></audio><details><summary>Transcript · <?=h($a['transcript_status']?:'queued')?></summary><?php if($a['transcript_text']):?><p><?=nl2br(h($a['transcript_text']))?></p><?php else:?><p class="meta">Transcription pending.</p><?php endif?></details><?php endif?><a href="/annotation.php?id=<?=h($a['public_id'])?>">Open annotation</a></article><?php endforeach?></section><aside><div class="card"><h3>Source history</h3><?php foreach($versions as $i=>$v):?><div class="historyItem"><strong>Version <?=h((string)$v['version_number'])?></strong><div class="meta"><?=h($v['captured_at'])?></div><?php if($v['screenshot_path']):?><a href="<?=h(source_evidence_url($source['public_id'],(int)$v['id']))?>" target="_blank" rel="noopener">Snapshot</a> · <?php endif?><?php if(isset($versions[$i+1])):?><a href="/source-compare.php?id=<?=h($source['public_id'])?>&from=<?=h((string)$versions[$i+1]['id'])?>&to=<?=h((string)$v['id'])?>">Compare with previous</a><?php endif?></div><?php endforeach?></div><?php if($events):?><div class="card"><h3>Change events</h3><?php foreach($events as $e):?><div class="historyItem"><span class="badge <?=$e['target_changed']?'warn':''?>"><?=h(ucfirst($e['change_type']))?></span><div>v<?=h((string)$e['previous_number'])?> → v<?=h((string)$e['new_number'])?></div><p class="meta"><?=h($e['diff_summary'])?></p></div><?php endforeach?></div><?php endif?></aside></main><?php if($u):?><script>const csrf=<?=json_encode(csrf_token())?>;document.querySelector('#watch')?.addEventListener('click',async e=>{const r=await fetch('/api/extension.php?action=watch_source',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({source:<?=json_encode($source['public_id'])?>})});const j=await r.json();if(j.ok)e.currentTarget.textContent=j.data.watched?'Watching':'Watch source';});</script><?php endif?></body></html>
